inputs = ['afz', 'uakx', 'iivvy', 'uhi', 'jv']
outputs = ['duhxz', 'xbduhkx', 'iieeeey', 'xbhi', 'jee']

# Analyze each changed pair manually
for i, inp, outp in [(0, 'afz', 'duhxz'), (1, 'uakx', 'xbduhkx'), (2, 'iivvy', 'iieeeey'), (3, 'uhi', 'xbhi'), (4, 'jv', 'jee')]:
    print(f"Pair {i}: '{inp}' -> '{outp}'")

    # Find what changed by comparing character by character
    min_len = min(len(inp), len(outp))
    changes = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            changes.append((j, inp[j], outp[j]))

    # Handle cases where lengths differ
    if len(inp) > len(outp):
        for j in range(min_len, len(inp)):
            changes.append((j, inp[j], ''))
    elif len(outp) > len(inp):
        for j in range(min_len, len(outp)):
            changes.append((j, '', outp[j]))

    print(f"  Changes: {changes}")
    print()

